<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import type { Project,Task,User,Status } from '../types';
import { dateLabel,priorities } from '../types';
import { api,get } from '../services/api';
import { useUi } from '../stores/ui';
import TaskBoard from '../components/TaskBoard.vue';
import TaskDialog from '../components/TaskDialog.vue';
import ProjectDialog from '../components/ProjectDialog.vue';
import ProgressIndicator from '../components/ProgressIndicator.vue';
import MemberList from '../components/MemberList.vue';
import ConfirmDialog from '../components/ConfirmDialog.vue';
const route=useRoute(),router=useRouter(),ui=useUi(),project=ref<Project|null>(null),tasks=ref<Task[]>([]),members=ref<User[]>([]),loading=ref(true),tab=ref('board');
const editProject=ref(false),taskDialog=ref(false),selected=ref<Task|null>(null),initialStatus=ref<Status>('todo'),confirm=ref<InstanceType<typeof ConfirmDialog>>();
const search=ref(''),priority=ref<string|null>(null),assignee=ref<number|null>(null);
const filtered=computed(()=>tasks.value.filter(t=>t.title.toLowerCase().includes(search.value.toLowerCase())&&(!priority.value||t.priority===priority.value)&&(!assignee.value||t.assigned_user_id===assignee.value)));
async function load(){try{const id=Number(route.params.id);const result=await Promise.all([get<Project>('/projects/'+id),get<Task[]>('/projects/'+id+'/tasks'),get<User[]>('/projects/'+id+'/members')]);[project.value,tasks.value,members.value]=result;}catch(e){ui.fail(e);project.value=null;}finally{loading.value=false;}}
function create(status:Status='todo'){selected.value=null;initialStatus.value=status;taskDialog.value=true;}
function edit(task:Task){selected.value=task;taskDialog.value=true;}
async function move(id:number,status:Status){if(tasks.value.find(t=>t.id===id)?.status===status)return;try{await api.patch('/tasks/'+id+'/status',{status});await load();ui.notify('Uzdevuma statuss atjaunināts.');}catch(e){ui.fail(e);}}
async function remove(){if(!project.value||!await confirm.value?.ask('Dzēst projektu?','Projekts un visi tā uzdevumi tiks neatgriezeniski dzēsti.'))return;try{await api.delete('/projects/'+project.value.id);await router.push('/projects');ui.notify('Projekts dzēsts.');}catch(e){ui.fail(e);}}
onMounted(load);watch(()=>route.params.id,load);
</script>
<template><v-btn to="/projects" variant="text" prepend-icon="mdi-arrow-left" class="mb-4 px-0">Visi projekti</v-btn><v-progress-linear v-if="loading" indeterminate color="primary"/><template v-else-if="project"><div class="page-heading"><div><div class="eyebrow">PROJEKTA DARBA TELPA</div><h1>{{project.name}}</h1><p>{{project.description}}</p><div class="d-flex align-center ga-4 mt-3 text-body-2 text-medium-emphasis"><span><v-icon icon="mdi-calendar-outline" size="17"/> {{dateLabel(project.deadline)}}</span><span><v-icon icon="mdi-account-group-outline" size="18"/> {{members.length}} dalībnieki</span></div></div><div class="d-flex ga-2"><v-btn v-if="project.role==='owner'" variant="outlined" icon="mdi-pencil-outline" aria-label="Rediģēt projektu" @click="editProject=true"/><v-btn color="primary" prepend-icon="mdi-plus" size="large" @click="create()">Jauns uzdevums</v-btn></div></div><v-card class="project-summary"><div class="summary-progress"><ProgressIndicator :value="project.progress" :completed="Number(project.completed_tasks)" :total="Number(project.total_tasks)"/></div><span><strong>{{Number(project.total_tasks)-Number(project.completed_tasks)}}</strong> atlikuši</span><span :class="Number(project.overdue_tasks)?'text-error':''"><strong>{{project.overdue_tasks}}</strong> nokavēti</span></v-card><v-tabs v-model="tab" color="primary" class="mb-6 border-b"><v-tab value="board" prepend-icon="mdi-view-column-outline">Uzdevumu dēlis</v-tab><v-tab value="team" prepend-icon="mdi-account-group-outline">Komanda</v-tab><v-tab v-if="project.role==='owner'" value="settings" prepend-icon="mdi-cog-outline">Projekta iestatījumi</v-tab></v-tabs><template v-if="tab==='board'"><div class="filter-toolbar"><v-text-field v-model="search" label="Meklēt uzdevumu" prepend-inner-icon="mdi-magnify" hide-details density="compact" class="search-field"/><v-select v-model="priority" :items="priorities" label="Prioritāte" clearable hide-details density="compact" class="filter-select"/><v-select v-model="assignee" :items="members" item-title="name" item-value="id" label="Atbildīgais" clearable hide-details density="compact" class="filter-select"/></div><TaskBoard :tasks="filtered" @edit="edit" @move="move" @create="create"/><p class="board-help"><v-icon icon="mdi-information-outline" size="15"/> Velc kartīti uz citu kolonnu vai atver to, lai mainītu statusu.</p></template><MemberList v-else-if="tab==='team'" :members="members" :project-id="project.id" :owner="project.role==='owner'" @changed="load"/><v-card v-else class="pa-7"><h2 class="mb-3">Projekta iestatījumi</h2><v-btn color="primary" class="mb-8" @click="editProject=true">Rediģēt informāciju</v-btn><v-divider class="mb-6"/><h3 class="mb-2">Dzēst projektu</h3><p class="text-medium-emphasis mb-4">Šī darbība dzēsīs arī visus projekta uzdevumus un dalību projektā.</p><v-btn color="error" variant="tonal" @click="remove">Dzēst projektu</v-btn></v-card><TaskDialog v-model="taskDialog" :task="selected" :project-id="project.id" :members="members" :initial-status="initialStatus" @saved="load"/><ProjectDialog v-model="editProject" :project="project" @saved="load"/></template><v-alert v-else type="warning" variant="tonal">Projekts nav pieejams vai to neizdevās ielādēt.<v-btn variant="text" @click="load">Mēģināt vēlreiz</v-btn></v-alert><ConfirmDialog ref="confirm"/></template>

